/* A&A Creative Studio — private front-end writing workspace. No external JS dependencies. */
(function () {
'use strict';
const root = document.getElementById('aacs-root');
if (!root) return;
const CFG = window.AACS_CONFIG || {};
const MODES = [
  ['dashboard','⌂','Dashboard'],['writing','✎','Writing Desk'],['ideas','✧','Idea Lab'],
  ['bible','▣','Story Bible'],['scripts','▤','Scripts'],['poetry','♬','Poetry & Rhymes'],
  ['templates','▦','Templates'],['projects','▱','Projects'],['collab','♧','Collaboration'],
  ['export','⇩','Export & Publish'],['coach','✧','AI Writing Coach'],['settings','⚙','Settings']
];
const WRITING_FONTS = [
 ['Georgia','Georgia,serif'],['Times New Roman','"Times New Roman",Times,serif'],['Arial','Arial,Helvetica,sans-serif'],['Courier New','"Courier New",Courier,monospace'],
 ['EB Garamond','"EB Garamond",Georgia,serif'],['Cormorant Garamond','"Cormorant Garamond",Georgia,serif'],['Lora','Lora,Georgia,serif'],['Merriweather','Merriweather,Georgia,serif'],
 ['Libre Baskerville','"Libre Baskerville",Georgia,serif'],['Playfair Display','"Playfair Display",Georgia,serif'],['Crimson Text','"Crimson Text",Georgia,serif'],['Spectral','Spectral,Georgia,serif'],
 ['Alegreya','Alegreya,Georgia,serif'],['Literata','Literata,Georgia,serif'],['Bitter','Bitter,Georgia,serif'],['Roboto Slab','"Roboto Slab",Georgia,serif'],
 ['Source Serif 4','"Source Serif 4",Georgia,serif'],['Inter','Inter,Arial,sans-serif'],['Roboto','Roboto,Arial,sans-serif'],['Open Sans','"Open Sans",Arial,sans-serif'],
 ['Montserrat','Montserrat,Arial,sans-serif'],['Nunito Sans','"Nunito Sans",Arial,sans-serif'],['Poppins','Poppins,Arial,sans-serif'],['Noto Naskh Arabic','"Noto Naskh Arabic",Georgia,serif']
];
function fontName(){const raw=s.prefs.font||'Georgia';return ({serif:'Georgia',sans:'Arial',mono:'Courier New'})[raw]|| (WRITING_FONTS.some(f=>f[0]===raw)?raw:'Georgia');}
function fontOptions(){return WRITING_FONTS.map(([name])=>`<option value="${esc(name)}" ${fontName()===name?'selected':''}>${esc(name)}</option>`).join('');}
function clampFontSize(v){const n=parseInt(v,10);return Number.isFinite(n)?Math.max(12,Math.min(48,n)):18;}
let fontPrefTimer=null;
function changeEditorFont(next){s.prefs.font=WRITING_FONTS.some(f=>f[0]===next)?next:'Georgia';updateFontControls();queueFontPreferenceSave();}
function changeEditorFontSize(next){s.prefs.fontSize=String(clampFontSize(next));updateFontControls();queueFontPreferenceSave();}
function updateFontControls(){const f=$('#aacs-editor-font'),n=$('#aacs-editor-size');if(f)f.value=fontName();if(n)n.value=String(clampFontSize(s.prefs.fontSize||18));applyEditorPrefs();}
function queueFontPreferenceSave(){if(fontPrefTimer)clearTimeout(fontPrefTimer);fontPrefTimer=setTimeout(async()=>{fontPrefTimer=null;try{await api('prefs','POST',{font:fontName(),fontSize:String(clampFontSize(s.prefs.fontSize||18))});}catch(e){note('Font preference could not be saved: '+e.message,true);}},500);}

const TEMPLATES = [
 ['Novel Chapter','chapter','Chapter Title','Start with a strong moment. Introduce conflict, build tension and end with an engaging question.'],
 ['Short Story','chapter','Short Story','A beginning that intrigues, a meaningful turning point and an earned ending.'],
 ['Film Screenplay','script','Untitled Screenplay','FADE IN:\n\nEXT. CITY STREET - NIGHT\n\nA figure walks into the rain.\n\n                         CHARACTER\n             We have to leave.'],
 ['Television Episode','script','Episode One','TEASER\n\nINT. OFFICE - DAY\n\nA mysterious envelope waits on the desk.'],
 ['Video Game Quest','script','Quest: The Missing Relic','QUEST OBJECTIVE:\nNPC:\nPLAYER CHOICES:\nOUTCOMES:'],
 ['Documentary Script','script','Documentary Outline','OPENING IMAGE:\nNARRATION:\nINTERVIEW QUESTIONS:\nB-ROLL:\nCLOSING:'],
 ['Poem','poetry','Untitled Poem','Through silent skies I chase the light\nAnd turn my doubts to stars at night'],
 ['Song Lyrics','poetry','New Song','VERSE 1:\n\nCHORUS:\n\nVERSE 2:\n\nBRIDGE:'],
 ['Blog Article','content','Blog Article','Working title:\nAudience:\nIntroduction:\nKey point 1:\nKey point 2:\nConclusion:'],
 ['Website Landing Page','content','Landing Page Copy','Headline:\nSubheadline:\nBenefits:\nProof:\nCall to action:'],
 ['Social Media Post','content','Social Announcement','Hook:\nMain message:\nCall to action:\nHashtags:'],
 ['Advertising Copy','content','Advertisement','Audience:\nProblem:\nSolution:\nOffer:\nCTA:'],
 ['Business Proposal','content','Proposal','Executive summary:\nScope:\nDeliverables:\nTimeline:\nTerms:'],
 ['Speech','content','Speech','Opening:\nThe main message:\nStory:\nClosing call to action:'],
 ['Podcast Episode','script','Podcast Script','INTRO MUSIC\nHOST:\nSEGMENT 1:\nGUEST QUESTIONS:\nOUTRO:'],
 ['Children’s Story','chapter','Children’s Story','Meet the main character:\nAn unexpected adventure:\nA lesson learned:'],
 ['Product Description','content','Product Description','Who is it for?\nKey features:\nBenefits:\nSpecifications:\nCall to action:'],
 ['Email Newsletter','content','Newsletter','Subject line:\nPreview text:\nGreeting:\nUpdate:\nCTA:'],
 ['Character Profile','character','New Character','Name:\nAge:\nGoal:\nFear:\nStrength:\nFlaw:\nSecret:\nArc:'],
 ['Worldbuilding Notes','location','New Location','Place:\nAtmosphere:\nHistory:\nCulture:\nRules:\nConflicts:']
];
const WORDS = {light:['night','bright','sight','flight','might','right','height','kite'],night:['light','bright','sight','flight','might','right'],
 day:['way','say','stay','play','away','gray','may'],dream:['stream','gleam','beam','seem','theme'],
 fire:['desire','higher','choir','spire'],heart:['start','part','art','apart'],love:['above','dove','glove'],
 time:['rhyme','chime','climb','sublime'],rain:['pain','gain','again','train','remain'],
 sea:['free','be','tree','key','me'],stone:['alone','known','grown','shown'],
 blue:['true','you','new','through'],sky:['high','fly','try','why'],
 gold:['old','bold','cold','told'],star:['far','are','car'],
 world:['unfurled','twirled','curled'],song:['long','strong','belong'],
 away:['day','say','stay','play'],end:['friend','bend','send','mend']};
const s = {tab:'dashboard', projects:[], project:null, docs:[], doc:null, prefs:{}, user:null, aiReady:false, aiProvider:CFG.aiProvider||"gemini", aiConsent:false,
  aiText:'', aiUsed:0, aiPrompt:'', aiAction:'ask', status:'', busy:false, revisions:[],
  rhymeQuery:'light', rhymeScheme:'ABAB', selectedTemplate:null, mobileNav:false, aiOpen:true, docDirty:false,
  lastSaved:'', aiPanelTab:'suggestions', modal:null, backup:null, exportLayout:{}, covers:{front:false,back:false}, coverPreviews:{front:'',back:''}, wc:0, editorFormat:'paragraph', settingsSection:'overview', templateFilter:'all', projectFilter:'all', adminSettings:CFG.adminSettings||{}, adminSummary:CFG.adminSummary||{}, settingsBusy:false};
let saveTimer=null, inFlight=false, savePromise=null;
const $=(sel,base=root)=>base.querySelector(sel);
const $$=(sel,base=root)=>Array.from(base.querySelectorAll(sel));
const esc = v => String(v===undefined||v===null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const strip = html => {const d=document.createElement('div');d.innerHTML=html||'';return d.textContent||'';};
const cleanText = v => String(v||'').replace(/\r\n?/g,'\n');
const words = v => (strip(v).trim().match(/\S+/g)||[]).length;
const fmtDate = v => v ? new Date(v+'Z').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : '';
const icon = v => ({novel:'✦',screenplay:'▤',poetry:'♬',article:'☷',content:'▦',game:'✧',other:'▣'})[v]||'▣';
const allowed=(m)=>['export','settings','coach'].includes(m)||!!(CFG.modules||{})[m];
const writable=()=>!s.project || s.project.role!=='viewer';
function note(t,err=false){s.status=t;let el=$('#aacs-toast');if(el){el.textContent=t;el.className='aacs-toast on'+(err?' error':'');setTimeout(()=>{if(el.textContent===t)el.classList.remove('on');},4500);}}
async function api(endpoint, method='GET', data){
 const options={method,credentials:'same-origin',headers:{'X-WP-Nonce':CFG.nonce,'Accept':'application/json'}};
 if(data!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}
 const resp=await fetch(CFG.api+endpoint,options);let json;
 try{json=await resp.json()}catch(e){throw Error('Invalid server response. Check your connection to the A&A Studio service.');}
 if(!resp.ok)throw Error(json.message||'Server error ('+resp.status+')');return json;
}
function pHead(){return `<header class="aacs-top"><div class="aacs-brand"><a href="${esc(CFG.home||'/')}" aria-label="A&A Pictures home"><img src="${esc(CFG.logo)}" alt="A&A Pictures"></a><div><strong>CREATIVE STUDIO</strong><small>WRITE · IMAGINE · CREATE</small></div></div><div class="aacs-head-right"><span class="aacs-session">● PRIVATE WRITING SPACE</span><a class="aacs-back-site" href="${esc(CFG.home||'/')}">Visit A&A Pictures ↗</a><button class="aacs-btn gold mini aacs-head-create" data-action="new-project">+ New Project</button><span class="aacs-user">${esc((s.user?.name||'Writer').slice(0,32))}</span><button class="aacs-hamb" data-action="menu" aria-label="Toggle navigation" aria-expanded="${s.mobileNav?'true':'false'}">☰</button></div></header>`;}
function pNav(){return `<aside class="aacs-nav ${s.mobileNav?'show':''}" aria-label="Creative Studio navigation"><div class="aacs-nav-label">WORKSPACE</div>${MODES.filter(([k])=>allowed(k)&&k!=='settings').map(([k,ico,label])=>`<button class="${s.tab===k?'active':''}" data-tab="${k}" aria-current="${s.tab===k?'page':'false'}"><span>${ico}</span>${label}</button>`).join('')}<div class="aacs-nav-label aacs-nav-lower">ACCOUNT</div><button class="${s.tab==='settings'?'active':''}" data-tab="settings"><span>⚙</span>Settings & Profile</button>${CFG.isAdmin?`<button class="${s.tab==='admin'?'active':''}" data-tab="admin"><span>⚒</span>Admin Controls</button>`:''}<div class="aacs-nav-spacer"></div><div class="aacs-nav-foot"><span>✧</span><b>Creator workspace</b><small>Your work stays private until you share it.</small><button data-tab="export">Export manuscript ↗</button></div></aside>`;}
function pShell(content){root.innerHTML=pHead()+`<div class="aacs-app-layout">${pNav()}<div class="aacs-workspace">${content}</div></div><div id="aacs-toast" class="aacs-toast" role="status"></div>`;root.classList.toggle('aacs-reduce-motion',s.prefs.reduceMotion==='1');root.classList.toggle('aacs-high-contrast',s.prefs.highContrast==='1');}
function sidePanel(){
 return `<aside class="aacs-side"><div class="aacs-panel-head"><h3>▱ My Projects</h3><button class="aacs-btn mini gold" data-action="new-project">+ New</button></div>
 ${s.projects.length?s.projects.slice(0,12).map(p=>`<button class="aacs-project-row ${s.project?.id===p.id?'selected':''}" data-project="${p.id}"><span class="aacs-project-ico">${icon(p.type)}</span><span><b>${esc(p.title)}</b><small>${esc(p.type)} · ${esc(p.role)}</small></span></button>`).join(''):`<p class="aacs-muted">No projects yet. Create one to start writing.</p>`}
 ${s.project?`<div class="aacs-side-label">${esc(s.project.title)} / Documents</div><div class="aacs-side-scroll">${s.docs.map(d=>`<button class="aacs-doc-row ${d.id===s.doc?.id?'active':''}" data-doc="${d.id}"><span>☷</span><span>${esc(d.title)}</span><small>${d.kind}</small></button>`).join('')}</div><button class="aacs-btn outline full" data-action="new-document" ${!writable()?'disabled':''}>+ New Document</button>`:''}
 <div class="aacs-side-bottom"><button data-tab="projects">View all projects ⇢</button></div></aside>`;
}
function intro(kicker,title,sub){return `<div class="aacs-intro"><small class="aacs-kicker">${esc(kicker)}</small><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>`;}
function dashboard(){let count=s.projects.length;let projects=s.projects.slice(0,4);return `<main class="aacs-page aacs-dashboard"><div class="aacs-dash-kicker">✦ A&A CREATIVE STUDIO / YOUR WORKSPACE</div><div class="aacs-dash-hero"><div><small class="aacs-kicker">WELCOME BACK, ${esc((s.user?.name||'WRITER').split(' ')[0].toUpperCase())}</small><h1>Where Imagination<br>Becomes a Masterpiece.</h1><p>Your private creative universe for scripts, stories, poetry, and content. Build it one word at a time.</p><button class="aacs-btn gold" data-tab="writing">✎ Open Writing Desk</button> <button class="aacs-btn outline" data-action="new-project">+ New Project</button></div></div><div class="aacs-stats"><div><small>ACTIVE PROJECTS</small><b>${count}</b><span>In your library</span></div><div><small>WORDS IN OPEN PROJECT</small><b>${s.docs.reduce((n,d)=>n+words(d.content),0).toLocaleString()}</b><span>Current project drafts</span></div><div><small>AI WRITING COACH</small><b>${s.aiReady?'Ready':'Offline'}</b><span>${s.aiReady?'Available on request':'Key not configured'}</span></div><div><small>DAILY WRITING TARGET</small><b>${esc(s.prefs.goal||500)}</b><span>Words</span></div></div><div class="aacs-dash-grid"><section class="aacs-panel padded"><div class="aacs-row between"><h2>Continue your projects</h2><button class="aacs-btn outline mini" data-tab="projects">All projects ↗</button></div>${projects.length?projects.map(p=>`<button class="aacs-dash-project" data-project="${p.id}"><span class="aacs-dash-project-art type-${esc(p.type)}">${icon(p.type)}</span><span><b>${esc(p.title)}</b><small>${esc(p.type)} · Last updated ${esc(fmtDate(p.updated))}</small></span><span>→</span></button>`).join(''):`<div class="aacs-empty"><p>No projects yet.</p><button class="aacs-btn gold" data-action="new-project">Create your first project</button></div>`}</section><section class="aacs-panel padded"><h2>Quick start</h2><div class="aacs-quick-grid">${[['writing','✎','Writing Desk'],['ideas','✧','Find Ideas'],['scripts','▤','Screenplay'],['poetry','♬','Poetry & Rhymes'],['templates','▦','Templates'],['bible','▣','Story Bible']].map(([k,i,t])=>`<button data-tab="${k}" ${!allowed(k)?'disabled':''}><span>${i}</span>${t}</button>`).join('')}</div><div class="aacs-dash-tip"><b>✧ Writing guidance</b><p>Ask your AI partner for an outline, fresh approach, critique or rewrite — only when you choose.</p><button data-tab="coach">Open writing coach ↗</button></div></section></div></main>`;}
function projectPicker(){return `<div class="aacs-inline-select"><label>Active project</label><select id="aacs-project-select"><option value="">Select a project</option>${s.projects.map(p=>`<option value="${p.id}" ${p.id===s.project?.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div>`;}
function emptyTab(title,sub,kind='chapter'){return `<div class="aacs-empty aacs-focus-empty"><div>✦</div><h2>${esc(title)}</h2><p>${esc(sub)}</p><div class="aacs-row centered"><button class="aacs-btn gold" data-action="new-project">Create project</button>${s.project?`<button class="aacs-btn outline" data-newkind="${kind}">Create document</button>`:''}</div></div>`;}
function docList(kind){return s.docs.filter(d=> !kind || d.kind===kind);}
function contentEditor(){const d=s.doc;if(!d)return emptyTab('Your writing desk is ready','Select or create a document to begin.');
 return `<div class="aacs-editor-card"><div class="aacs-editor-header"><div><small>WRITING DESK / ${esc(s.project?.title||'PROJECT')}</small><input id="aacs-doc-title" aria-label="Document title" value="${esc(d.title)}" ${!writable()?'disabled':''}></div><div class="aacs-saving" id="aacs-saving">${s.docDirty?'Unsaved changes':'✓ Saved'}</div></div>
 <div class="aacs-toolbar"><label class="aacs-toolbar-font"><span class="aacs-visually-hidden">Writing font</span><select id="aacs-editor-font" aria-label="Writing font" title="Choose from 24 writing fonts">${fontOptions()}</select></label><div class="aacs-font-resize" role="group" aria-label="Writing font size"><button type="button" data-action="font-minus" aria-label="Decrease editor font size" title="Smaller writing text">A−</button><input id="aacs-editor-size" aria-label="Editor font size in pixels" type="number" min="12" max="48" step="1" value="${clampFontSize(s.prefs.fontSize||18)}"><button type="button" data-action="font-plus" aria-label="Increase editor font size" title="Larger writing text">A+</button><span class="aacs-font-unit">px</span></div><span class="aacs-toolbar-sep"></span><select id="aacs-format" aria-label="Format"><option value="p">Paragraph</option><option value="h2">Heading</option><option value="blockquote">Quote</option></select><button title="Bold" data-format="bold"><b>B</b></button><button title="Italic" data-format="italic"><i>I</i></button><button title="Underline" data-format="underline"><u>U</u></button><button title="Unordered list" data-format="insertUnorderedList">☷</button><button title="Ordered list" data-format="insertOrderedList">☰</button><button data-action="insert-link" title="Insert link">♧</button><span class="aacs-toolbar-sep"></span><button data-action="history" title="Version history">↶ Revisions</button><button data-action="focus" title="Toggle focus mode">⛶ Focus</button><button data-action="save" title="Save now">Save</button><button data-action="delete-doc" title="Delete document" ${!writable()?'disabled':''}>Delete</button></div>
 <div class="aacs-edit-scroll"><div class="aacs-editable" id="aacs-editable" contenteditable="${writable()?'true':'false'}" role="textbox" aria-label="Writing editor" aria-multiline="true" data-placeholder="Start your story here…">${d.content||''}</div></div>
 <div class="aacs-editor-foot">${s.prefs.showWordCount!=='0'?`<span id="aacs-wordcount">${words(d.content)} words</span>`:''}<span>${esc(d.kind)} · ${esc(s.prefs.language||'English')}</span><span>${writable()?'Autosave enabled':'Read only'}</span></div></div>`;}
function aiSide(){return `<aside class="aacs-ai"><div class="aacs-panel-head"><h3>✧ AI Writing Coach</h3><span class="aacs-pill">${s.aiReady?'A&A AI READY':'NOT CONFIGURED'}</span></div><p class="aacs-muted">Your writing assistant for brainstorming, rewriting and improvement. Every suggestion is optional.</p><p class="aacs-help">When you request AI help, your prompt and selected writing content are processed by a third-party AI service through A&amp;A Pictures. See the A&amp;A Pictures Privacy Policy for details.</p>
 <div class="aacs-ai-tabs"><button data-ai-action="suggest">Suggestions</button><button data-ai-action="brainstorm">Ideas</button><button data-ai-action="style">Improve</button></div>
 <div class="aacs-coach-hints" ${s.prefs.suggestions==='0'?'hidden':''}><div><b>◈ Refine your draft</b><small>Select or write text, then request a rewrite.</small></div><div><b>♧ Explore alternatives</b><small>Ask for a different tone, plot twist or ending.</small></div><div><b>▤ Keep control</b><small>AI output is never inserted automatically.</small></div></div>
 <div class="aacs-coach-actions"><button data-ai-action="rewrite">↺ Rewrite</button><button data-ai-action="continue">▷ Continue</button><button data-ai-action="analyze">▥ Analyze</button><button data-ai-action="outline">☷ Outline</button></div>
 <label class="aacs-field"><span>Ask your creative partner</span><textarea id="aacs-ai-prompt" placeholder="Suggest an intriguing twist, polish a paragraph, explain pacing…">${esc(s.aiPrompt)}</textarea></label>
 <button class="aacs-btn gold full" data-action="ask-ai" ${!s.aiReady?'disabled':''}>✧ Ask AI</button>${!s.aiReady?`<div class="aacs-ai-setup-hint"><strong>AI connection needed — one-time setup.</strong><p>The website administrator configures the AI connection once. Writers approve only the suggestions they want to insert, not each AI request.</p>${CFG.isAdmin?`<a href="${esc(CFG.adminUrl)}" target="_blank" rel="noopener">Configure AI settings ↗</a>`:''}</div>`:''}
 <div class="aacs-ai-result" id="aacs-ai-result" ${s.aiText?'':'hidden'}><div class="aacs-row between"><b>AI suggestion</b><div><button data-action="copy-ai">Copy</button> <button data-action="append-ai" ${!writable()?'disabled':''}>Insert</button></div></div><div class="aacs-result-text" id="aacs-ai-text">${esc(s.aiText)}</div></div></aside>`;}
function writingTab(){return `<div class="aacs-three">${sidePanel()}<main class="aacs-main-column">${s.project?contentEditor():emptyTab('Welcome to the Writing Desk','Create or open a project to organize your drafts.')}</main>${aiSide()}</div>`;}
function ideasTab(){return `<main class="aacs-page">${intro('THE IDEA LAB','A Spark Can Become a World','Find concepts, develop possibilities and save the best ones into your own project.')}${projectPicker()}
 <div class="aacs-two"><div class="aacs-panel padded"><h2>✧ Brainstorm something extraordinary</h2><label class="aacs-field"><span>What are you imagining?</span><textarea id="aacs-idea-input" placeholder="A futuristic city where music is forbidden; an extraordinary film idea; ten article hooks…" rows="6"></textarea></label><div class="aacs-chips">${['Fantasy plot twists','Film concepts','Game quests','Blog topics','Character dilemmas','Unexpected endings'].map(v=>`<button data-idea="${esc(v)}">${esc(v)}</button>`).join('')}</div><div class="aacs-row"><button class="aacs-btn gold" data-action="ideas-ai" ${!s.aiReady?'disabled':''}>✧ Generate ideas</button><button class="aacs-btn outline" data-action="save-idea" ${!s.project?'disabled':''}>Save as my idea</button></div>${!s.aiReady?'<p class="aacs-help">Connect an AI key to generate suggestions. You can still save your own ideas.</p>':''}</div>
 <div class="aacs-panel padded"><h2>Creative development</h2><div class="aacs-feature-list">${[['Story premises','A one-sentence idea becomes a strong logline.'],['Genre & tone','Explore thriller, fantasy, romance, documentary and comedy.'],['Questions & conflict','Reveal what makes an idea interesting.'],['Alternative directions','Compare multiple ways to develop the same concept.']].map(v=>`<div><b>✧ ${v[0]}</b><span>${v[1]}</span></div>`).join('')}</div></div></div>${aiResultPage()}</main>`;}
function aiResultPage(){return `<div class="aacs-panel padded aacs-result-block" ${s.aiText?'':'hidden'} id="aacs-page-result"><div class="aacs-row between"><h2>✧ AI results</h2><div><button class="aacs-btn outline mini" data-action="copy-ai">Copy</button> <button class="aacs-btn gold mini" data-action="save-ai" ${!s.project?'disabled':''}>Save to project</button></div></div><pre class="aacs-pre">${esc(s.aiText)}</pre></div>`;}
function bibleTab(){const groups=[['character','Characters','Build personalities and relationships'],['location','Locations','Build immersive settings'],['timeline','Timeline','Keep events in order'],['research','Research','Source notes and world rules'],['outline','Outlines','Beats and structure']];return `<main class="aacs-page">${intro('STORY BIBLE','One World. No Lost Details.','Record characters, locations, research and timelines to maintain continuity across long projects.')}${projectPicker()}
 <div class="aacs-bible-grid">${groups.map(([kind,title,sub])=>`<section class="aacs-panel padded"><div class="aacs-row between"><div><h2>${esc(title)}</h2><p class="aacs-muted">${esc(sub)}</p></div><button class="aacs-btn gold mini" data-newkind="${kind}" ${!s.project||!writable()?'disabled':''}>+</button></div>${docList(kind).length?docList(kind).map(d=>`<button class="aacs-list-link" data-doc="${d.id}">${esc(d.title)} ↗</button>`).join(''):'<p class="aacs-help">No notes yet</p>'}</section>`).join('')}</div><button class="aacs-btn outline" data-ai-action="characters" ${!s.aiReady?'disabled':''}>✧ AI character suggestions</button>${aiResultPage()}</main>`;}
function scriptTab(){let doc=s.doc?.kind==='script'?s.doc:docList('script')[0];if(doc)s.doc=doc;return `<div class="aacs-three aacs-script-mode">${sidePanel()}<main class="aacs-main-column"><div class="aacs-mode-heading"><div><small>PROFESSIONAL SCREENPLAY DRAFTING</small><h2>▤ Script Studio</h2></div><button class="aacs-btn gold mini" data-newkind="script" ${!s.project||!writable()?'disabled':''}>+ New Script</button></div>${doc?contentEditor():emptyTab('Begin your screenplay','Write film, TV, documentary, game and podcast scripts using Fountain conventions.','script')}<div class="aacs-script-helper"><b>Insert screenplay element</b><div class="aacs-chips">${['Scene','Action','Character','Dialogue','Transition'].map(x=>`<button data-script="${x}" ${!doc||!writable()?'disabled':''}>${x}</button>`).join('')}</div><small>Export Fountain (.fountain) from the Export tab. Preview in browser print for PDF.</small></div></main>${aiSide()}</div>`;}
function rhymeEnds(){const q=(s.rhymeQuery||'').toLowerCase().match(/[a-z]+$/)?.[0]||'';let exact=WORDS[q];if(!exact){let suf=q.slice(-3);exact=Object.keys(WORDS).filter(k=>k!==q && k.endsWith(suf)).slice(0,14);}return exact||[];}
function estimateSyllables(w){w=w.toLowerCase().replace(/[^a-z]/g,'');if(!w)return 0;if(w.length<=3)return 1;w=w.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/,'').replace(/^y/,'');return Math.max(1,(w.match(/[aeiouy]{1,2}/g)||[]).length);}
function syllablePanelText(){let text=strip(s.doc?.content||'');let lines=text.split(/\n/).filter(x=>x.trim()).slice(0,8);if(!lines.length)return '<small>No verse lines written yet.</small>';return lines.map((l,i)=>'<div>'+esc('Line '+(i+1))+' <b>'+l.split(/\s+/).reduce((sum,w)=>sum+estimateSyllables(w),0)+' syllables*</b></div>').join('');}
function poetryTab(){let doc=s.doc?.kind==='poetry'?s.doc:docList('poetry')[0];if(doc)s.doc=doc;return `<div class="aacs-three">${sidePanel()}<main class="aacs-main-column"><div class="aacs-mode-heading"><div><small>VERSE · LYRICS · SOUND</small><h2>♬ Poetry & Rhymes</h2></div><button class="aacs-btn gold mini" data-newkind="poetry" ${!s.project||!writable()?'disabled':''}>+ New Poem</button></div>${doc?contentEditor():emptyTab('Find your rhythm','Create poems, lyrics and verses. Explore rhyme, rhythm and syllable counts.','poetry')}</main>
 <aside class="aacs-ai"><div class="aacs-panel-head"><h3>♬ Rhyme Assistant</h3></div><label class="aacs-field"><span>Find matching end sounds</span><input id="aacs-rhyme" value="${esc(s.rhymeQuery)}" placeholder="Enter a word"></label><div id="aacs-rhyme-words" class="aacs-chips aacs-rhyme-results">${rhymeEnds().map(w=>`<button data-rhyme-word="${esc(w)}">${esc(w)}</button>`).join('')||'<span>No local matches. Try AI for sound-aware ideas.</span>'}</div><label class="aacs-field"><span>Rhyme pattern</span><select id="aacs-scheme">${['AABB','ABAB','ABBA','AAAA','ABCB'].map(v=>`<option ${s.rhymeScheme===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="aacs-rhyme-lines">${s.rhymeScheme.split('').map((l,i)=>`<div><b>${l}</b><span>Line ${i+1} ends with sound ${l}</span></div>`).join('')}</div><div class="aacs-syllable-lines" id="aacs-syllables">${syllablePanelText()}</div><p class="aacs-help">*Local rhyme and syllable suggestions are approximate. Use AI for broader language-aware suggestions.</p><button class="aacs-btn gold full" data-ai-action="poetry" ${!s.aiReady?'disabled':''}>✧ Improve verse with AI</button>${s.aiText?`<pre class="aacs-pre">${esc(s.aiText)}</pre>`:''}</aside></div>`;}
function templatesTab(){return `<main class="aacs-page">${intro('READY-TO-WRITE FORMATS','Write Anything Beautifully','Choose a structure, then make it yours. Every template creates an editable document.')}${projectPicker()}<div class="aacs-chips aacs-template-filters">${[['all','All'],['chapter','Stories'],['script','Scripts'],['poetry','Poetry'],['content','General'],['character','Characters']].map(([k,l])=>`<button data-template-filter="${k}" class="${s.templateFilter===k?'aacs-chip-active':''}">${l}</button>`).join('')}</div><div class="aacs-template-grid">${TEMPLATES.map((x,i)=>`<button class="aacs-template-card" data-template="${i}" ${s.templateFilter!=='all' && x[1]!==s.templateFilter?'hidden':''} ${!s.project||!writable()?'disabled':''}><span>${icon(x[1])}</span><strong>${esc(x[0])}</strong><small>${esc(x[1])} template</small><em>Use template →</em></button>`).join('')}</div>${!s.project?'<p class="aacs-help">Choose or create a project to use templates.</p>':''}</main>`;}
function projectsTab(){const filtered=s.projectFilter==='all'?s.projects:s.projects.filter(p=>p.type===s.projectFilter);return `<main class="aacs-page">${intro('YOUR CREATIVE LIBRARY','My Projects & Library','Browse manuscripts, screenplays, poems and saved content across your private workspace.')}<div class="aacs-row between"><div class="aacs-chips">${[['all','All projects'],['novel','Novels'],['screenplay','Scripts'],['poetry','Poetry'],['article','Articles'],['content','Content'],['game','Game stories']].map(([k,l])=>`<button data-project-filter="${k}" class="${s.projectFilter===k?'aacs-chip-active':''}">${l}</button>`).join('')}</div><button class="aacs-btn gold" data-action="new-project">+ New project</button></div><div class="aacs-gallery-grid">${filtered.map(p=>`<article class="aacs-gallery-card"><button data-project="${p.id}" class="aacs-gallery-art type-${esc(p.type)}"><span>${icon(p.type)}</span></button><div><small>${esc(p.type.toUpperCase())} · ${esc(p.role)}</small><h3>${esc(p.title)}</h3><p>${esc(p.description||'Your creative writing project')}</p><span class="aacs-row between"><small>Edited ${esc(fmtDate(p.updated))}</small><button class="aacs-btn outline mini" data-project="${p.id}">Open →</button></span>${p.role==='owner'?`<button class="aacs-delete-small" data-deleteproject="${p.id}">Delete project</button>`:''}</div></article>`).join('')||'<div class="aacs-empty"><h3>No matching projects</h3><p>Start a project or change the filter.</p></div>'}</div></main>`;}
function collabTab(){let members=s.project?.members||[];return `<main class="aacs-page">${intro('WRITING TOGETHER','Collaborate Without Losing Control','Invite verified A&A Pictures customers to your project as writers or readers. Only project owners can grant access.')}${projectPicker()}
 <div class="aacs-two"><section class="aacs-panel padded"><h2>Invite a collaborator</h2><p class="aacs-muted">Sharing is private. The invited person must already have a verified A&A Pictures customer account.</p><label class="aacs-field"><span>Writer email</span><input type="email" id="aacs-share-email" placeholder="writer@example.com"></label><label class="aacs-field"><span>Access level</span><select id="aacs-share-role"><option value="viewer">Viewer — read only</option><option value="editor">Editor — can write and save</option></select></label><button class="aacs-btn gold" data-action="invite" ${!CFG.allowCollaboration||!s.project||s.project.role!=='owner'?'disabled':''}>Grant project access</button></section>
 <section class="aacs-panel padded"><h2>Project access</h2>${s.project?`<div class="aacs-list-link">${esc(s.user?.name)} — ${esc(s.project.role==='owner'?'Owner':s.project.role)}</div>${members.map(m=>`<div class="aacs-member"><span>${esc(m.name)} <small>${esc(m.email)}</small></span><b>${esc(m.role)}</b>${s.project?.role==='owner'?`<button data-remove-member="${m.id}" title="Remove access">×</button>`:''}</div>`).join('')||'<p class="aacs-help">No collaborators yet</p>'}`:'<p class="aacs-help">Select a project to manage access</p>'}</section></div></main>`;}
function exportTab(){
 const l=Object.assign({pageSize:'a4',orientation:'portrait',marginTop:.8,marginBottom:.8,marginInside:.9,marginOutside:.65,gutter:.15,mirror:true,fontSize:12,lineSpacing:1.45,pageNumbers:true,numberStyle:'decimal',numberPosition:'bottom-center',startNumber:1,titlePage:true,chapterBreak:true,coverMode:'none',coverFit:'cover',sameBack:false,numberAfterCover:true},s.exportLayout||{});
 const select=(name,options)=>`<select data-layout="${name}">${options.map(([value,label])=>`<option value="${esc(value)}" ${l[name]===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
 const num=(name,min,max,step)=>`<input type="number" data-layout="${name}" min="${min}" max="${max}" step="${step}" value="${esc(l[name])}">`;
 const check=(name,label)=>`<label class="aacs-export-check"><input type="checkbox" data-layout="${name}" ${l[name]?'checked':''}> ${label}</label>`;
 const controls=(kind,scope,label,disabled)=>`<button class="aacs-btn ${kind==='pdf'?'gold':'outline'}" data-format-download="${kind}" data-scope="${scope}" ${disabled?'disabled':''}>⇩ Download ${label} (.${kind})</button>`;
 return `<main class="aacs-page">${intro('PREPARE YOUR MANUSCRIPT','Book Layout & Downloads','Download an editable Word file or a paginated PDF. Format the final book, poetry collection, or screenplay.')} ${projectPicker()}
 <div class="aacs-two aacs-export-main"><section class="aacs-panel padded"><h2>Manuscript layout</h2><p class="aacs-muted">These preferences are saved to your writer account and applied to both exports.</p>
 <div class="aacs-export-grid">
 <label class="aacs-field"><span>Paper / book size</span>${select('pageSize',[['a4','A4 — 8.27 × 11.69 in'],['letter','US Letter — 8.5 × 11 in'],['a5','A5 — 5.83 × 8.27 in'],['trade6x9','Trade paperback — 6 × 9 in']])}</label>
 <label class="aacs-field"><span>Orientation</span>${select('orientation',[['portrait','Portrait'],['landscape','Landscape']])}</label>
 <label class="aacs-field"><span>Top margin (in)</span>${num('marginTop',.35,2.5,.05)}</label>
 <label class="aacs-field"><span>Bottom margin (in)</span>${num('marginBottom',.35,2.5,.05)}</label>
 <label class="aacs-field"><span>Inside / binding margin (in)</span>${num('marginInside',.35,2.5,.05)}</label>
 <label class="aacs-field"><span>Outside margin (in)</span>${num('marginOutside',.35,2.5,.05)}</label>
 <label class="aacs-field"><span>Gutter / binding allowance (in)</span>${num('gutter',0,1.5,.05)}</label>
 <label class="aacs-field"><span>Font size (pt)</span>${num('fontSize',9,20,1)}</label>
 <label class="aacs-field"><span>Line spacing</span>${select('lineSpacing',[[1,'Single'],[1.15,'1.15'],[1.3,'1.3'],[1.45,'1.45'],[1.5,'1.5'],[2,'Double']])}</label>
 </div><div class="aacs-export-checks">${check('mirror','Mirror inner/outer margins for left and right book pages')}${check('titlePage','Include a cover/title page')}${check('chapterBreak','Start each new chapter on a new page')}${check('pageNumbers','Display page numbers')}</div>
 <h2 class="aacs-export-subtitle">Book cover images</h2>
 <p class="aacs-muted">Upload your original cover art (JPEG, PNG or WebP, maximum 5 MB). Saved privately to your writer account; the images are not placed in the public Media Library.</p>
 <div class="aacs-export-grid">
 <label class="aacs-field"><span>Cover mode</span>${select('coverMode',[['none','No image cover'],['front','Front cover only'],['front-back','Front and back covers']])}</label>
 <label class="aacs-field"><span>Image placement</span>${select('coverFit',[['cover','Fill page / crop to fit'],['contain','Entire image / white edges'],['stretch','Stretch to page']])}</label>
 </div>
 <div class="aacs-export-checks">${check('sameBack','Use front image as the back cover')}${check('numberAfterCover','Start page numbers after the front cover')}</div>
 <div class="aacs-cover-grid">
 ${['front','back'].map(side=>`<div class="aacs-cover-tile"><b>${side==='front'?'Front cover':'Back cover'}</b>
 <div class="aacs-cover-thumb" data-cover-thumb="${side}">${s.coverPreviews[side]?`<img src="${s.coverPreviews[side]}" alt="${side} cover preview">`:`<span>${s.covers[side]?'Cover saved — preview loading':'No image uploaded'}</span>`}</div>
 <label class="aacs-btn outline aacs-cover-file">↑ ${s.covers[side]?'Replace':'Upload'} ${side} image <input type="file" data-cover-upload="${side}" accept="image/jpeg,image/png,image/webp"></label>
 <button class="aacs-btn outline mini" data-cover-delete="${side}" ${s.covers[side]?'':'disabled'}>Remove image</button></div>`).join('')}
 </div>
 <p class="aacs-help">For front-only exports, only the front image appears. For front-and-back exports, the back image appears at the end. Front and back cover pages have no page numbers. All content margins apply to manuscript pages, not to covers. To keep the title printed on your cover, include it in your uploaded artwork.</p>
 <h2 class="aacs-export-subtitle">Page numbering</h2><div class="aacs-export-grid">
 <label class="aacs-field"><span>Page number style</span>${select('numberStyle',[['decimal','1, 2, 3…'],['lowerRoman','i, ii, iii…'],['upperRoman','I, II, III…']])}</label>
 <label class="aacs-field"><span>Position</span>${select('numberPosition',[['bottom-center','Bottom center'],['bottom-outside','Bottom outside corners'],['top-right','Top right']])}</label>
 <label class="aacs-field"><span>Start numbering at</span>${num('startNumber',1,9999,1)}</label>
 </div><button class="aacs-btn gold" data-action="save-layout">✓ Save Book Layout</button></section>
 <section class="aacs-panel padded aacs-export-downloads"><h2>Download your writing</h2><p class="aacs-muted">Select your manuscript or a single open document. Your work remains private and is not published online.</p>
 <h3>Current document</h3><p class="aacs-muted">${esc(s.doc?.title||'Open a document first')}</p><div class="aacs-export-buttons">${controls('docx','document','Word',!s.doc)}${controls('pdf','document','PDF',!s.doc)}</div>
 <h3>Full manuscript / book</h3><p class="aacs-muted">Combine your project's chapters, scripts, poems, and content documents in document order. Story Bible research notes stay out of the manuscript.</p><div class="aacs-export-buttons">${controls('docx','project','Book as Word',!s.project)}${controls('pdf','project','Book as PDF',!s.project)}</div>
 <div class="aacs-export-box"><b>Other formats</b><div class="aacs-export-buttons">${[['txt','Plain text'],['md','Markdown'],['html','HTML'],['fountain','Fountain'],['print','Print / Unicode PDF']].map(([k,t])=>`<button class="aacs-btn outline" data-export="${k}" ${!s.doc?'disabled':''}>${t}</button>`).join('')}</div></div>
 <div class="aacs-export-box"><b>Project backup</b><p class="aacs-muted">Download all project records and Story Bible notes in JSON.</p><button class="aacs-btn outline" data-export="json" ${!s.project?'disabled':''}>⇩ Download Project JSON</button></div>
 <button class="aacs-btn outline" data-export="printbook" ${!s.project?'disabled':''}>Print complete book / Unicode PDF</button><p class="aacs-help">DOCX preserves Unicode text, including Urdu and Arabic. Direct PDF uses standard Latin-script fonts in this release; for Urdu, Arabic and other complex scripts choose <b>Print / Unicode PDF</b> (single document or full book) using your browser's font renderer. DOCX page numbering is recalculated by Microsoft Word when opened. Browser-generated PDFs use the print dialog's page-number/header options.</p>
 </section></div></main>`;
}
async function loadCoverPreviews(){
 for(const side of ['front','back']){
  if(!s.covers[side]||s.coverPreviews[side])continue;
  try{const result=await api('covers/'+side);s.coverPreviews[side]=result.image||'';
   const thumb=$(`[data-cover-thumb="${side}"]`);if(thumb&&s.coverPreviews[side])thumb.innerHTML=`<img src="${s.coverPreviews[side]}" alt="${side} cover preview">`;
  }catch(e){note('Could not load the '+side+' cover preview',true);}
 }
}
async function uploadCover(side,file){
 if(!file)return;
 if(file.size>5*1024*1024){note('Cover files must be 5 MB or smaller',true);return;}
 s.exportLayout=Object.assign({},s.exportLayout,getLayoutValues());
 const data=new FormData();data.append('file',file,file.name);
 const result=await fetch(CFG.api+'covers/'+side,{method:'POST',headers:{'X-WP-Nonce':CFG.nonce},credentials:'same-origin',body:data});
 const response=await result.json();if(!result.ok)throw new Error(response.message||'Cover upload failed');
 s.covers[side]=true;s.coverPreviews[side]='';note('Cover uploaded. Save layout settings before exporting.');render();await loadCoverPreviews();
}
async function deleteCover(side){
 s.exportLayout=Object.assign({},s.exportLayout,getLayoutValues());
 await api('covers/'+side,'DELETE');s.covers[side]=false;s.coverPreviews[side]='';render();note('Cover removed');
}
function getLayoutValues(){const layout={};$$('[data-layout]').forEach(el=>{let key=el.dataset.layout;let value=el.type==='checkbox'?el.checked:el.value;if(el.type==='number'||key==='lineSpacing')value=Number(value);layout[key]=value;});return layout;}
async function saveLayout(){s.exportLayout=await api('layout','POST',getLayoutValues());note('Book layout saved for Word and PDF downloads');return true;}
async function downloadManuscript(format,scope){
 if(await flushSave()===false){note('Save the current document first',true);return;}
 await saveLayout();
 const id=scope==='project'?s.project?.id:s.doc?.id;
 if(!id){note('Choose a project or document first',true);return;}
 const url=new URL(CFG.downloadEndpoint,window.location.href);
 url.searchParams.set('action','aacs_download');url.searchParams.set('format',format);
 url.searchParams.set('scope',scope);url.searchParams.set('id',String(id));url.searchParams.set('_wpnonce',CFG.downloadNonce);
 const a=document.createElement('a');a.href=url.href;a.style.display='none';document.body.appendChild(a);a.click();a.remove();
 note('Preparing your '+format.toUpperCase()+' download.');
}
const USER_SECTIONS=[['overview','Writing Preferences','✦'],['language','Language & Accessibility','◎'],['voice','AI Behaviour & Voice','✧'],['saving','Autosave & Revision History','↶'],['privacy','Privacy & Content Control','♧'],['goals','Writing Goals & Focus','◫'],['profile','Writer Profile','♙']];
const ADMIN_SECTIONS=[['overview','Admin Overview','⚙'],['roles','Roles & Permissions','♟'],['credits','Usage Credits & Limits','◈'],['safety','Safety & Compliance','⛨'],['privacy-admin','Privacy & Retention','♧'],['analytics','Analytics & Audit Logs','▥'],['modules','Modules & Integrations','▦'],['backup','Backup & Maintenance','⇩']];
function fieldSelect(id,label,values,val){return `<label class="aacs-field"><span>${esc(label)}</span><select id="${id}">${values.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function prefField(key,label,values){return fieldSelect('pref-'+key,label,values,s.prefs[key]||'');}
function prefCheck(key,label,description,def='1'){const checked=String(s.prefs[key]===undefined?def:s.prefs[key])==='1';return `<label class="aacs-setting-toggle"><span><b>${esc(label)}</b><small>${esc(description)}</small></span><input type="checkbox" data-pref="${esc(key)}" ${checked?'checked':''}></label>`;}
function settingPanel(title,content,description=''){return `<section class="aacs-panel padded aacs-settings-panel"><h2>${title}</h2>${description?`<p class="aacs-muted">${description}</p>`:''}${content}</section>`;}
function settingsShell(sectionList,title,description,body){return `<main class="aacs-page aacs-settings-page">${intro('CREATIVE STUDIO SETTINGS',title,description)}<div class="aacs-settings-layout"><aside class="aacs-settings-menu">${sectionList.map(([key,label,ico])=>`<button data-settings-section="${key}" class="${s.settingsSection===key?'active':''}"><span>${ico}</span>${esc(label)}</button>`).join('')}</aside><div class="aacs-settings-detail">${body}</div></div></main>`;}
function settingsTab(){const p=s.prefs;const v=(k,d='')=>esc(p[k]===undefined?d:p[k]);let body='';
if(s.settingsSection==='overview')body=settingPanel('Your writing workspace',`<div class="aacs-setting-cards">${USER_SECTIONS.slice(1).map(([key,title,ico])=>`<button class="aacs-setting-card" data-settings-section="${key}"><span>${ico}</span><b>${esc(title)}</b><small>Customize your Creative Studio →</small></button>`).join('')}</div><p class="aacs-help">Preferences are saved privately to your A&A Pictures writing account. Only the optional AI calls send selected text to the configured provider.</p>`);
if(s.settingsSection==='language')body=settingPanel('Language & Accessibility',`<div class="aacs-setting-columns">${prefField('language','Primary writing language',['English','Urdu','Arabic','Spanish','French','German','Portuguese','Chinese','Japanese','Korean','Turkish','Thai'].map(x=>[x,x]))}${prefField('font','Writing font — 24 choices',WRITING_FONTS.map(([name])=>[name,name]))}<label class="aacs-field"><span>Editor font size (12–48 px)</span><input id="pref-fontSize" type="number" min="12" max="48" value="${v('fontSize','18')}"></label><label class="aacs-field"><span>Line spacing</span><input id="pref-lineHeight" type="number" step="0.1" min="1.2" max="2.5" value="${v('lineHeight','1.9')}"></label></div>${prefCheck('highContrast','Higher contrast','Improve readability of the writing panels','0')}${prefCheck('reduceMotion','Reduce animations','Use a calmer interface with minimal movement','0')}${prefCheck('spellcheck','Browser spell check','Use your browser’s spelling support in the writing editor','1')}`);
if(s.settingsSection==='voice')body=settingPanel('AI Behaviour & Your Voice',`${prefField('aiStyle','Coaching style',[['Supportive','Supportive'],['Direct','Direct'],['Detailed','Detailed'],['Minimal','Minimal']])}${prefField('aiLanguage','AI response language',[['auto','Match my writing'],['English','English'],['Urdu','Urdu'],['Spanish','Spanish'],['French','French'],['Arabic','Arabic']])}${prefField('coachingDetail','Suggestion detail',[['concise','Concise guidance'],['balanced','Balanced'],['deep','Detailed critique']])}${prefCheck('suggestions','Show AI writing suggestions','AI output always requires your approval before insertion','1')}<div class="aacs-callout"><b>✧ Original author voice</b><p>The AI coach is optional; it won’t automatically edit your work. You decide whether to copy or insert any suggestion.</p></div>`);
if(s.settingsSection==='saving')body=settingPanel('Autosave & Version History',`${prefCheck('autosave','Automatically save drafts','Save changes as you type while connected to the Studio','1')}${prefCheck('saveReminder','Remind me to save','Show unsaved changes when leaving a document','1')}${prefCheck('showWordCount','Show word count','Display live writing statistics in the editor','1')}<div class="aacs-callout"><b>↶ Revision history</b><p>Open any draft in the Writing Desk and select Revisions to review and restore saved revisions.</p><button class="aacs-btn outline" data-tab="writing">Go to Writing Desk</button></div>`);
if(s.settingsSection==='privacy')body=settingPanel('Privacy & Content Control',`<div class="aacs-feature-list"><div><b>Private by default</b><span>Projects remain private A&A project records, accessible only to owners and explicitly assigned collaborators.</span></div><div><b>Share with permission</b><span>Control access using the Collaboration screen. Grant editor or read-only permissions to existing site users.</span></div><div><b>AI request control</b><span>Document contents are sent to your configured AI provider only when you run a coach action; your account's API provider policies apply.</span></div><div><b>Export or remove work</b><span>Use Export for local copies or Projects to delete documents and projects. Deleting a project is permanent.</span></div></div><div class="aacs-row"><button class="aacs-btn outline" data-tab="collab">Manage project sharing</button><button class="aacs-btn outline" data-tab="export">Download a backup</button></div>`);
if(s.settingsSection==='goals')body=settingPanel('Writing Goals & Focus',`<div class="aacs-setting-columns"><label class="aacs-field"><span>Daily word goal</span><input id="pref-goal" type="number" min="100" max="30000" value="${v('goal','500')}"></label>${prefField('theme','Editor appearance',[['cinematic','Cinematic dark'],['minimal','Distraction free']])}</div>${prefCheck('focus','Start writing in focus mode','Hide helper panels when opening the writing desk','0')}<div class="aacs-callout"><b>◫ Focus tools</b><p>Use Focus Mode in the Writing Desk to hide the project list and AI helper while you draft.</p><button data-tab="writing" class="aacs-btn outline">Open writing desk</button></div>`);
if(s.settingsSection==='profile')body=settingPanel('Writer Profile',`<label class="aacs-field"><span>Pen name</span><input id="pref-penName" maxlength="100" value="${v('penName',s.user?.name||'')}"></label><label class="aacs-field"><span>Favorite writing genre</span><input id="pref-writingGenre" maxlength="100" value="${v('writingGenre','')}"></label><label class="aacs-field"><span>Writer biography (private)</span><textarea id="pref-bio" maxlength="500" rows="5">${v('bio','')}</textarea></label><div class="aacs-callout">Your A&A Pictures account email is <b>${esc(s.user?.email||'')}</b>. Update your customer password in My A&A Account.</div>`);
return settingsShell(USER_SECTIONS,'Writer Preferences','Configure your language, writing tools, privacy, goals and account preferences.',body+`${s.settingsSection==='overview'||s.settingsSection==='privacy'?'':`<div class="aacs-setting-actions"><button class="aacs-btn gold" data-action="save-settings-section">✓ Save Preferences</button><span>Your choices are private to your account.</span></div>`}`);}
function adminTab(){if(!CFG.isAdmin)return `<main class="aacs-page">${intro('ACCESS','Administrators only','You do not have permission to manage Creative Studio.')}</main>`;const settings=Object.assign({provider:'gemini',gemini_model:'gemini-3.8-flash',model:'gpt-4.1-mini',daily_limit:25,collaboration:true,modules:{},retention_days:0},s.adminSettings||{});const sums=s.adminSummary||{};let body='';
if(s.settingsSection==='overview')body=settingPanel('Creative Studio administration',`<div class="aacs-admin-kpis"><div><b>${Number(sums.projects||0).toLocaleString()}</b><span>Private projects</span></div><div><b>${Number(sums.documents||0).toLocaleString()}</b><span>Saved documents</span></div><div><b>${Number(sums.writers||0).toLocaleString()}</b><span>Registered WordPress accounts</span></div></div><div class="aacs-setting-cards">${ADMIN_SECTIONS.slice(1).map(([k,name,ico])=>`<button class="aacs-setting-card" data-settings-section="${k}"><span>${ico}</span><b>${esc(name)}</b><small>Open controls →</small></button>`).join('')}</div>`);
if(s.settingsSection==='roles')body=settingPanel('Roles & Permissions',`<div class="aacs-feature-list"><div><b>Owner</b><span>Can edit, export, delete, and share their projects.</span></div><div><b>Editor</b><span>Can view and edit shared drafts but cannot change sharing or delete the entire project.</span></div><div><b>Viewer</b><span>Can read a shared project without editing.</span></div></div><label class="aacs-setting-toggle"><span><b>Enable collaboration</b><small>Allow project owners to grant access to existing site accounts</small></span><input type="checkbox" data-admin="collaboration" ${settings.collaboration?'checked':''}></label>`);
if(s.settingsSection==='credits')body=settingPanel('AI Usage & Limits',`<div class="aacs-setting-columns"><label class="aacs-field"><span>AI requests per writer / UTC day</span><input type="number" min="1" max="200" data-admin="daily_limit" value="${esc(settings.daily_limit)}"></label><label class="aacs-field"><span>Active provider</span><select data-admin="provider"><option value="gemini" ${settings.provider==='gemini'?'selected':''}>Google Gemini</option><option value="openai" ${settings.provider==='openai'?'selected':''}>OpenAI</option></select></label><label class="aacs-field"><span>Gemini model</span><select data-admin="gemini_model"><option value="gemini-3.8-flash" ${settings.gemini_model==='gemini-3.8-flash'?'selected':''}>Gemini 3.8 Flash</option><option value="gemini-3.5-flash-lite" ${settings.gemini_model==='gemini-3.5-flash-lite'?'selected':''}>Gemini 3.5 Flash-Lite</option><option value="gemini-2.5-flash" ${settings.gemini_model==='gemini-2.5-flash'?'selected':''}>Gemini 2.5 Flash (legacy)</option><option value="gemini-2.5-flash-lite" ${settings.gemini_model==='gemini-2.5-flash-lite'?'selected':''}>Gemini 2.5 Flash-Lite (legacy)</option></select></label></div><div class="aacs-callout"><b>API key status: ${settings.aiConfigured?'Configured':'Not configured'}</b><p>Set or rotate the API key for the active provider in the protected WordPress settings page. Tokens and billing are managed separately by your API provider; this screen sets request limits, not payment credits.</p><a href="${esc(CFG.adminUrl||'#')}" target="_blank" rel="noopener">Open secure AI connection settings ↗</a></div>`);
if(s.settingsSection==='safety')body=settingPanel('Safety & Compliance',`<div class="aacs-feature-list"><div><b>Owner control</b><span>AI never automatically inserts suggestions into the author’s writing.</span></div><div><b>AI provider limitations</b><span>Generated material should be checked by authors for originality, factual accuracy and rights.</span></div><div><b>Role-based access</b><span>WordPress authentication and project owner permissions protect editing and downloads.</span></div><div><b>Content reporting & moderation</b><span>Advanced reporting queues and automatic copyright screening are not yet included in this version.</span></div></div>`);
if(s.settingsSection==='privacy-admin')body=settingPanel('Privacy & Data Retention',`<label class="aacs-field"><span>Retention policy record (days; 0 means indefinite)</span><input type="number" min="0" max="3650" data-admin="retention_days" value="${esc(settings.retention_days)}"></label><p class="aacs-help">This value documents your retention policy. Automated data deletion is not enabled; WordPress hosting backups and privacy requests must be managed separately.</p><div class="aacs-feature-list"><div><b>Private drafts</b><span>Stored as nonpublic WordPress records.</span></div><div><b>AI processing</b><span>Only requested prompts and context are sent to the configured provider.</span></div><div><b>Writer data rights</b><span>Writers can export projects as JSON. Site administrators should review WordPress privacy export/erase workflows.</span></div></div>`);
if(s.settingsSection==='analytics')body=settingPanel('Analytics & Audit Visibility',`<div class="aacs-admin-kpis"><div><b>${Number(sums.projects||0).toLocaleString()}</b><span>Projects</span></div><div><b>${Number(sums.documents||0).toLocaleString()}</b><span>Documents</span></div><div><b>${Number(sums.writers||0).toLocaleString()}</b><span>Site accounts</span></div></div><div class="aacs-callout"><b>Account-wide counts only</b><p>These metrics come from current WordPress records. Detailed usage charts, writer activity timelines and tamper-evident audit logs will require event tracking and are not active.</p></div>`);
if(s.settingsSection==='modules')body=settingPanel('Modules & Integrations',`<div class="aacs-module-grid">${Object.entries(settings.modules||{}).map(([k,enabled])=>`<label class="aacs-setting-toggle"><span><b>${esc(k.replace(/_/g,' ').replace(/\b\w/g,x=>x.toUpperCase()))}</b><small>${enabled?'Enabled':'Disabled'}</small></span><input type="checkbox" data-admin-module="${esc(k)}" ${enabled?'checked':''}></label>`).join('')}</div><div class="aacs-callout"><b>Configured AI integration</b><p>Connect Gemini or OpenAI using the secure WordPress administration settings. Enabling a module changes navigation availability; it does not create additional paid services.</p><a href="${esc(CFG.adminUrl||'#')}" target="_blank" rel="noopener">AI configuration ↗</a></div>`);
if(s.settingsSection==='backup')body=settingPanel('Backup & Maintenance',`<div class="aacs-feature-list"><div><b>Writer backups</b><span>Every writer can download their own project JSON, DOCX and PDF exports.</span></div><div><b>WordPress database backups</b><span>Use Hostinger’s scheduled site backups. This plugin does not yet include server-side backup scheduling.</span></div><div><b>Safeguard updates</b><span>Create a full hosting backup before upgrading the plugin. Test exports and saving on staging.</span></div></div><div class="aacs-row"><button data-tab="export" class="aacs-btn outline">View writer exports</button><a class="aacs-btn outline" href="${esc(CFG.adminUrl||'#')}" target="_blank" rel="noopener">WordPress plugin settings ↗</a></div>`);
return settingsShell(ADMIN_SECTIONS,'Admin Settings','Control project access, AI usage, modules and operational safeguards.',body+`${['roles','credits','privacy-admin','modules'].includes(s.settingsSection)?'<div class="aacs-setting-actions"><button class="aacs-btn gold" data-action="save-admin">✓ Save Admin Settings</button><span>Changes affect all Creative Studio users.</span></div>':''}`);}
function coachTab(){return `<main class="aacs-page">${intro('AI CREATIVE PARTNER','AI Writing Coach','A private place to request suggestions, brainstorm, analyze, and improve your drafts — always with author approval.')}${projectPicker()}<div class="aacs-two"><section class="aacs-panel padded"><h2>Writing under review</h2><p class="aacs-muted">${esc(s.doc?.title||'Open a document from the Writing Desk')}</p><div class="aacs-coach-preview">${esc(strip(s.doc?.content||'No document selected. You can still ask for original ideas.').slice(0,2500))}</div><div class="aacs-chips">${[['suggest','Suggestions'],['rewrite','Rewrite'],['analyze','Analyze'],['style','Style'],['outline','Outline'],['continue','Continue']].map(([a,label])=>`<button data-ai-action="${a}" ${!s.aiReady?'disabled':''}>${label}</button>`).join('')}</div></section><section class="aacs-panel padded"><h2>Ask your writing coach</h2><label class="aacs-field"><span>What can I help you create?</span><textarea id="aacs-ai-prompt" rows="7" placeholder="Suggest an alternative ending, tighten my dialogue, or help improve the tone…">${esc(s.aiPrompt)}</textarea></label><button class="aacs-btn gold" data-action="ask-ai" ${!s.aiReady?'disabled':''}>✧ Generate suggestions</button>${!s.aiReady?`<p class="aacs-help">AI assistance is temporarily unavailable. Please contact A&A support.</p>`:''}</section></div>${aiResultPage()}</main>`;}
function render(){let content;switch(s.tab){case 'dashboard':content=dashboard();break;case 'writing':content=writingTab();break;case 'ideas':content=ideasTab();break;case 'bible':content=bibleTab();break;case 'scripts':content=scriptTab();break;case 'poetry':content=poetryTab();break;case 'templates':content=templatesTab();break;case 'projects':content=projectsTab();break;case 'collab':content=collabTab();break;case 'export':content=exportTab();break;case 'settings':content=settingsTab();break;case 'admin':content=adminTab();break;case 'coach':content=coachTab();break;default:content=dashboard();}pShell(content);if(s.tab==='export')loadCoverPreviews();if(s.doc && ['writing','scripts','poetry'].includes(s.tab))applyEditorPrefs();}
function applyEditorPrefs(){const el=$('#aacs-editable');if(!el)return;const choice=WRITING_FONTS.find(f=>f[0]===fontName())||WRITING_FONTS[0];el.style.fontFamily=choice[1];el.style.fontSize=clampFontSize(s.prefs.fontSize||18)+'px';el.style.lineHeight=String(s.prefs.lineHeight||1.9);el.spellcheck=s.prefs.spellcheck!=='0';}
async function init(){try{const b=await api('bootstrap');Object.assign(s,{projects:b.projects||[],user:b.user,prefs:b.prefs||{},exportLayout:b.exportLayout||{},covers:b.covers||{front:false,back:false},aiReady:b.aiReady,aiProvider:b.aiProvider||CFG.aiProvider||"gemini",adminSettings:b.adminSettings||{},adminSummary:b.adminSummary||{}});
 const remembered=parseInt(sessionStorage.getItem('aacs_project')||'0',10); const first=s.projects[0]?.id||0;const last=s.projects.some(p=>p.id===remembered)?remembered:first;if(last)await openProject(last,false);
 render();}catch(e){root.innerHTML=`<div class="aacs-error">Unable to load the workspace: ${esc(e.message)}. Refresh or sign back in.</div>`;}}
async function openProject(id,doRender=true){if(await flushSave()===false)throw Error('Your draft is not saved. Try again before switching projects.');const data=await api('projects/'+id);s.project=data.project;s.docs=data.documents||[];
 const prev=s.doc?.id;s.doc=s.docs.find(d=>d.id===prev)||s.docs[0]||null;sessionStorage.setItem('aacs_project',id);if(doRender)render();}
async function selectDoc(id,tab){if(await flushSave()===false)throw Error('Your draft is not saved. Try again before switching documents.');const d=s.docs.find(d=>d.id===id);if(!d)return; s.doc=d;
 if(tab)s.tab=tab;else if(d.kind==='poetry')s.tab='poetry';else if(d.kind==='script')s.tab='scripts';else s.tab='writing';render();}
async function createDoc(kind='chapter',title='Untitled',content=''){if(!s.project){note('Create or select a project first.',true);return;}if(!writable()){note('Read-only project',true);return;}
 if(await flushSave()===false)return note('Save the current draft before creating another document',true);try{const d=await api('documents','POST',{projectId:s.project.id,kind,title,content});s.docs.push(d);s.doc=d;s.tab=kind==='script'?'scripts':kind==='poetry'?'poetry':'writing';render();note('Document created');}catch(e){note(e.message,true);}}
async function flushSave(){if(saveTimer){clearTimeout(saveTimer);saveTimer=null;}if(inFlight)return savePromise;if(!s.docDirty||!s.doc)return true;
 inFlight=true;savePromise=(async()=>{const doc=s.doc, title=doc.title, content=doc.content;const saving=$('#aacs-saving');if(saving)saving.textContent='Saving…';
 try{const saved=await api('documents/'+doc.id,'POST',{title,content});const idx=s.docs.findIndex(d=>d.id===doc.id);if(idx>=0)s.docs[idx]=Object.assign({},saved, {content:doc.content,title:doc.title});
 if(s.doc?.id===doc.id && s.doc.content===content && s.doc.title===title){s.docDirty=false;const el=$('#aacs-saving');if(el)el.textContent='✓ Saved';}
 else if(s.doc?.id===doc.id){s.docDirty=true;saveTimer=setTimeout(flushSave,1200);}
 }catch(e){const el=$('#aacs-saving');if(el)el.textContent='Save failed — retry';note(e.message,true);return false;}finally{inFlight=false;savePromise=null;}})();return savePromise;}
function dirty(){if(!s.doc||!writable())return;s.docDirty=true;const el=$('#aacs-saving');if(el)el.textContent='Unsaved changes';
 if(saveTimer)clearTimeout(saveTimer);if(s.prefs.autosave!=='0')saveTimer=setTimeout(flushSave,1400);}
function download(name,body,mime='text/plain'){const blob=new Blob([body],{type:mime});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),2000);}
function safeFilename(name){return String(name||'document').replace(/[^\w\s-]/g,'').trim().replace(/\s+/g,'-').slice(0,70)||'document';}
function toMarkdown(html){return String(html||'').replace(/<br\s*\/?\s*>/gi,'\n').replace(/<\/(p|div|h[1-6]|li|blockquote)>/gi,'\n\n').replace(/<li[^>]*>/gi,'- ').replace(/<strong[^>]*>|<b[^>]*>/gi,'**').replace(/<\/(strong|b)>/gi,'**').replace(/<em[^>]*>|<i[^>]*>/gi,'*').replace(/<\/(em|i)>/gi,'*').replace(/<[^>]+>/g,'').replace(/\n{3,}/g,'\n\n').trim();}
function printEntireBook(){
 if(!s.project)return note('Choose a project first',true);
 const docs=s.docs.filter(d=>['chapter','script','poetry','content'].includes(d.kind));
 if(!docs.length)return note('No manuscript chapters found',true);
 const l=Object.assign({pageSize:'a4',marginTop:.8,marginBottom:.8,marginInside:.9,marginOutside:.65,fontSize:12,lineSpacing:1.45,titlePage:true,chapterBreak:true},s.exportLayout||{});
 const sizes={a4:'A4',letter:'letter',a5:'A5',trade6x9:'6in 9in'};
 const pageSize=sizes[l.pageSize]||'A4';
 const title='<section class="title-page"><h1>'+esc(s.project.title)+'</h1><p>'+esc(s.user?.name||'')+'</p></section>';
 const html=docs.map((d,i)=>'<article class="chapter" style="break-before:'+(i&&l.chapterBreak?'page':'auto')+'"><h2>'+esc(d.title)+'</h2>'+(d.content||'')+'</article>').join('');
 const w=window.open('','_blank');if(!w){note('Allow popups for browser PDF printing',true);return;}
 w.document.write('<!doctype html><html><head><meta charset="UTF-8"><title>'+esc(s.project.title)+'</title><style>@page{size:'+pageSize+';margin:'+l.marginTop+'in '+l.marginOutside+'in '+l.marginBottom+'in '+l.marginInside+'in}body{font:'+l.fontSize+'pt/'+l.lineSpacing+' Georgia,serif;color:#111}.title-page{text-align:center;break-after:page;padding-top:22vh}.title-page h1{font-size:2em}.chapter h2{text-align:center}p{orphans:3;widows:3}</style></head><body>'+(l.titlePage?title:'')+html+'</body></html>');
 w.document.close();w.focus();setTimeout(()=>w.print(),500);
}
async function doExport(kind){if(await flushSave()===false)return;if(kind==='printbook'){printEntireBook();return;}if(kind==='json'){if(!s.project)return;const json=await api('export/'+s.project.id);download(safeFilename(s.project.title)+'.json',JSON.stringify(json,null,2),'application/json');return;}
 if(!s.doc)return;const name=safeFilename(s.doc.title),txt=strip(s.doc.content);
 if(kind==='txt')download(name+'.txt',txt);else if(kind==='md')download(name+'.md',toMarkdown(s.doc.content),'text/markdown');
 else if(kind==='fountain')download(name+'.fountain',toMarkdown(s.doc.content),'text/plain');
 else if(kind==='html')download(name+'.html','<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+esc(s.doc.title)+'</title></head><body><h1>'+esc(s.doc.title)+'</h1>'+s.doc.content+'</body></html>','text/html');
 else if(kind==='print'){const l=Object.assign({pageSize:'a4',marginTop:.8,marginBottom:.8,marginInside:.9,marginOutside:.65,fontSize:12,lineSpacing:1.45},s.exportLayout||{});let w=window.open('','_blank');if(!w){note('Allow popups to print',true);return;}const sizes={a4:'A4',letter:'letter',a5:'A5',trade6x9:'6in 9in'};w.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+esc(s.doc.title)+'</title><style>@page{size:'+(sizes[l.pageSize]||'A4')+';margin:'+l.marginTop+'in '+l.marginOutside+'in '+l.marginBottom+'in '+l.marginInside+'in}body{font:'+l.fontSize+'pt/'+l.lineSpacing+' Georgia,serif;color:#111}h1{text-align:center;page-break-after:avoid}p{margin:.65em 0;orphans:3;widows:3}</style></head><body><h1>'+esc(s.doc.title)+'</h1>'+s.doc.content+'</body></html>');w.document.close();w.focus();setTimeout(()=>w.print(),350);}
 note('Export prepared');}
async function runAI(action, prompt, context){if(!s.aiReady){note('AI assistance is currently unavailable',true);return;}
 if(!s.aiConsent){const accept=confirm('A&A AI Writing Coach: Your request and selected writing context will be sent to an external AI provider for processing. Do not submit confidential client drafts without permission. See the A&A Pictures website Privacy Policy for details. Continue?');if(!accept)return;s.aiConsent=true;}
 if(s.busy)return;s.busy=true;const text=$('#aacs-ai-text');const result=$('#aacs-ai-result');if(text){text.textContent='Thinking…';result.hidden=false;}
 try{const x=await api('ai','POST',{action,prompt:prompt||'',context:context||'',projectId:s.project?.id||0,mode:s.tab});s.aiText=x.text;
 if(text)text.textContent=x.text;const page=$('#aacs-page-result');if(page){page.hidden=false;page.querySelector('.aacs-pre').textContent=x.text;}
 note('AI suggestion ready — review before using');}
 catch(e){note(e.message,true);if(text)text.textContent=e.message;}finally{s.busy=false;}}
function contextText(){let ed=$('#aacs-editable');let selection=window.getSelection()?.toString()||'';return selection || ed?.innerText || strip(s.doc?.content||'');}
function getEditor(){return $('#aacs-editable');}
function insertText(v){const ed=getEditor();if(!ed||!writable()){note('Open a writable document first',true);return;}
 ed.focus();document.execCommand('insertText',false,v);s.doc.content=ed.innerHTML;dirty();}
function openModal(html){let previous=$('.aacs-modal-wrap');if(previous)previous.remove();const wrap=document.createElement('div');wrap.className='aacs-modal-wrap';wrap.innerHTML=`<div class="aacs-modal-backdrop" data-action="close-modal"></div><div class="aacs-modal" role="dialog" aria-modal="true">${html}</div>`;root.appendChild(wrap);wrap.querySelector('input')?.focus();}
function newProjectModal(){openModal(`<h2>✧ Create a new project</h2><p class="aacs-muted">Every writer begins somewhere.</p><form id="aacs-form-new-project"><label class="aacs-field"><span>Project name</span><input required maxlength="120" name="title" placeholder="The Last Lantern"></label><label class="aacs-field"><span>Type of writing</span><select name="type">${[['novel','Novel or story'],['screenplay','Screenplay'],['poetry','Poetry / lyrics'],['article','Article / blog'],['content','Content writing'],['game','Game narrative'],['other','Other']].map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><label class="aacs-field"><span>Description (optional)</span><textarea name="description" placeholder="Describe your creative project"></textarea></label><div class="aacs-row"><button type="submit" class="aacs-btn gold">Create Project</button><button type="button" class="aacs-btn outline" data-action="close-modal">Cancel</button></div></form>`);}
function newDocumentModal(kind='chapter'){openModal(`<h2>✎ New ${esc(kind)}</h2><form id="aacs-form-new-document"><input type="hidden" name="kind" value="${esc(kind)}"><label class="aacs-field"><span>Document title</span><input required name="title" placeholder="Untitled ${esc(kind)}"></label><div class="aacs-row"><button type="submit" class="aacs-btn gold">Create Document</button><button type="button" class="aacs-btn outline" data-action="close-modal">Cancel</button></div></form>`);}
async function historyModal(){if(!s.doc)return;let list=await api('documents/'+s.doc.id+'/revisions');let html=`<h2>↶ Version history</h2><p class="aacs-muted">Up to 30 server revisions. Restoring an earlier version replaces the current draft, which you can revise again.</p>`+
 (list.length?list.map(x=>`<div class="aacs-revision"><div><b>${esc(fmtDate(x.date))}</b><small> · ${words(x.content)} words</small></div><button class="aacs-btn outline mini" data-restore="${x.id}">Restore</button></div>`).join(''):'<p>No revisions yet. Revisions are created when saved content changes.</p>')+`<button class="aacs-btn outline" data-action="close-modal">Close</button>`;
 openModal(html);}
function rhymeRefresh(){const el=$('#aacs-rhyme-words');if(el)el.innerHTML=rhymeEnds().map(w=>`<button data-rhyme-word="${esc(w)}">${esc(w)}</button>`).join('')||'<span>No local matches. Try AI for sound-aware ideas.</span>';}
root.addEventListener('click',async ev=>{
 const target=ev.target.closest('button,[data-action],[data-tab],[data-project],[data-doc],[data-export],[data-format-download],[data-template],[data-idea],[data-newkind],[data-ai-action],[data-format],[data-deleteproject],[data-rhyme-word],[data-script],[data-remove-member],[data-restore],[data-cover-delete],[data-settings-section],[data-project-filter],[data-template-filter]');if(!target)return;
 try{
 if(target.dataset.projectFilter){s.projectFilter=target.dataset.projectFilter;render();return;}
 if(target.dataset.templateFilter){s.templateFilter=target.dataset.templateFilter;render();return;}
 if(target.dataset.settingsSection){s.settingsSection=target.dataset.settingsSection;render();return;}
 if(target.dataset.tab){if(await flushSave()===false)return note('Save the current draft before switching tabs',true);s.tab=target.dataset.tab;if(['settings','admin'].includes(s.tab))s.settingsSection='overview';s.mobileNav=false;render();return;}
 if(target.dataset.project){await openProject(parseInt(target.dataset.project,10));if(s.tab==='dashboard'||s.tab==='projects')s.tab='writing';render();return;}
 if(target.dataset.doc){await selectDoc(parseInt(target.dataset.doc,10));return;}
 if(target.dataset.newkind){newDocumentModal(target.dataset.newkind);return;}
 if(target.dataset.template!==undefined){const t=TEMPLATES[parseInt(target.dataset.template,10)];await createDoc(t[1],t[2],'<p>'+esc(t[3]).replace(/\n/g,'<br>')+'</p>');return;}
 if(target.dataset.idea){const input=$('#aacs-idea-input');if(input){input.value=target.dataset.idea+': ';input.focus();}return;}
 if(target.dataset.formatDownload){await downloadManuscript(target.dataset.formatDownload,target.dataset.scope);return;}
 if(target.dataset.export){await doExport(target.dataset.export);return;}
 if(target.dataset.aiAction){const a=target.dataset.aiAction;const p=$('#aacs-ai-prompt')?.value||('Help me with '+a+' for my current writing');await runAI(a,p,contextText());return;}
 if(target.dataset.format){const editor=getEditor();if(editor){editor.focus();document.execCommand(target.dataset.format,false,null);s.doc.content=editor.innerHTML;dirty();}return;}
 if(target.dataset.rhymeWord){insertText(target.dataset.rhymeWord);return;}
 if(target.dataset.script){let sample={Scene:'\n\nINT. LOCATION - DAY\n\n',Action:'\nDescribe the action in present tense.\n',Character:'\n\n                         CHARACTER\n',Dialogue:'\n             What the character says.\n',Transition:'\n\n                                           CUT TO:\n'};insertText(sample[target.dataset.script]||'');return;}
 if(target.dataset.deleteproject){if(!confirm('Permanently delete this project and all its documents? This cannot be undone.'))return;await api('projects/'+target.dataset.deleteproject,'DELETE');s.projects=s.projects.filter(p=>p.id!=target.dataset.deleteproject);if(s.project?.id==target.dataset.deleteproject){s.project=null;s.doc=null;s.docs=[];sessionStorage.removeItem('aacs_project');}render();note('Project deleted');return;}
 if(target.dataset.removeMember){if(!confirm('Remove this collaborator’s access?'))return;const members=await api('collaborators/'+s.project.id+'/'+target.dataset.removeMember,'DELETE');s.project.members=members;render();note('Access removed');return;}
 if(target.dataset.coverDelete){await deleteCover(target.dataset.coverDelete);return;}
 if(target.dataset.restore){if(!confirm('Restore this revision? Your current draft will be replaced.'))return;const saved=await api('documents/'+s.doc.id+'/restore','POST',{revisionId:Number(target.dataset.restore)});s.doc=saved;s.docs=s.docs.map(d=>d.id===saved.id?saved:d);$('.aacs-modal-wrap')?.remove();render();note('Revision restored');return;}
 const action=target.dataset.action;
 if(action==='menu'){s.mobileNav=!s.mobileNav;$('.aacs-nav')?.classList.toggle('show',s.mobileNav);target.setAttribute('aria-expanded',s.mobileNav?'true':'false');return;}
 if(action==='close-modal'){$('.aacs-modal-wrap')?.remove();return;}
 if(action==='new-project'){newProjectModal();return;}
 if(action==='new-document'){newDocumentModal();return;}
 if(action==='save'){await flushSave();note('Saved');return;}
 if(action==='delete-doc'){if(!s.doc||!writable())return;if(!confirm('Permanently delete this document? This cannot be undone.'))return;
   if(saveTimer){clearTimeout(saveTimer);saveTimer=null;}s.docDirty=false;
   await api('documents/'+s.doc.id,'DELETE');s.docs=s.docs.filter(d=>d.id!==s.doc.id);s.doc=s.docs[0]||null;render();note('Document deleted');return;}

 if(action==='font-minus'){changeEditorFontSize(clampFontSize(s.prefs.fontSize||18)-1);return;}
 if(action==='font-plus'){changeEditorFontSize(clampFontSize(s.prefs.fontSize||18)+1);return;}
 if(action==='focus'){root.classList.toggle('aacs-focus');return;}
 if(action==='history'){await historyModal();return;}
 if(action==='insert-link'){let url=prompt('Enter full link URL (https://...)');if(url && /^https:\/\//i.test(url)){getEditor()?.focus();document.execCommand('createLink',false,url);if(s.doc){s.doc.content=getEditor().innerHTML;dirty();}}return;}
 if(action==='ask-ai'){s.aiPrompt=$('#aacs-ai-prompt')?.value||'';await runAI('ask',s.aiPrompt||'Give practical writing suggestions.',contextText());return;}
 if(action==='ideas-ai'){const t=$('#aacs-idea-input')?.value||'';if(!t.trim())return note('Describe the idea first',true);await runAI('brainstorm',t,'');return;}
 if(action==='save-idea'){const t=$('#aacs-idea-input')?.value||'';if(!t.trim())return note('Type an idea first',true);await createDoc('idea','New idea — '+new Date().toLocaleDateString(),'<p>'+esc(t).replace(/\n/g,'<br>')+'</p>');return;}
 if(action==='copy-ai'){if(navigator.clipboard)await navigator.clipboard.writeText(s.aiText);note('Copied AI suggestion');return;}
 if(action==='append-ai'){insertText('\n\n'+s.aiText);note('Inserted suggestion — please review');return;}
 if(action==='save-ai'){await createDoc('idea','AI ideas — '+new Date().toLocaleDateString(),'<p>'+esc(s.aiText).replace(/\n/g,'<br>')+'</p>');return;}
 if(action==='invite'){if(!s.project)return;const email=$('#aacs-share-email').value,role=$('#aacs-share-role').value;const members=await api('collaborators/'+s.project.id,'POST',{email,role});s.project.members=members;render();note('Collaborator access granted');return;}
 if(action==='save-layout'){await saveLayout();return;}
 if(action==='save-settings-section'){
   const data={}; $$('[id^="pref-"]').forEach(el=>{let k=el.id.slice(5);data[k]=el.value;});$$('[data-pref]').forEach(el=>{data[el.dataset.pref]=el.checked?'1':'0';});
   s.prefs=await api('prefs','POST',data);applyEditorPrefs();note('Writer settings saved');render();return;
 }
 if(action==='save-admin'){
   if(!CFG.isAdmin)return note('Administrator access required',true);
   const data={modules:{}};$$('[data-admin]').forEach(el=>{data[el.dataset.admin]=el.type==='checkbox'?el.checked:el.value;});
   $$('[data-admin-module]').forEach(el=>{data.modules[el.dataset.adminModule]=el.checked;});
   const result=await api('admin','POST',data);s.adminSettings=result.settings;s.adminSummary=result.summary;s.aiProvider=result.settings?.provider||s.aiProvider;s.aiReady=!!result.settings?.aiConfigured;s.aiConsent=false;if(result.settings?.modules)CFG.modules=result.settings.modules;if(result.settings?.collaboration!==undefined)CFG.allowCollaboration=result.settings.collaboration;note('Administrative settings saved');render();return;
 }
 if(action==='save-prefs'){const pref={language:$('#pref-language').value,font:$('#pref-font').value,fontSize:$('#pref-size').value,goal:$('#pref-goal').value,aiStyle:$('#pref-ai-style').value};s.prefs=await api('prefs','POST',pref);note('Writing preferences saved');return;}
 }catch(e){note(e.message,true);}
});
root.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target;try{
 if(form.id==='aacs-form-new-project'){const fd=new FormData(form);const p=await api('projects','POST',Object.fromEntries(fd.entries()));s.projects.unshift(p);s.project=p;s.docs=[];s.doc=null;sessionStorage.setItem('aacs_project',p.id);$('.aacs-modal-wrap')?.remove();s.tab='writing';render();newDocumentModal(p.type==='screenplay'?'script':p.type==='poetry'?'poetry':p.type==='article'||p.type==='content'?'content':'chapter');}
 if(form.id==='aacs-form-new-document'){const fd=new FormData(form);$('.aacs-modal-wrap')?.remove();await createDoc(fd.get('kind'),fd.get('title'));}
 }catch(e){note(e.message,true);}});
root.addEventListener('input',ev=>{const e=ev.target;
 if(e.id==='aacs-editable' && s.doc){s.doc.content=e.innerHTML;dirty();const wc=$('#aacs-wordcount');if(wc)wc.textContent=words(s.doc.content)+' words';const sy=$('#aacs-syllables');if(sy)sy.innerHTML=syllablePanelText();}
 else if(e.id==='aacs-doc-title' && s.doc){s.doc.title=e.value;dirty();}
 else if(e.id==='aacs-rhyme'){s.rhymeQuery=e.value;rhymeRefresh();}
 else if(e.id==='aacs-ai-prompt'){s.aiPrompt=e.value;}
});
root.addEventListener('change',async ev=>{const e=ev.target;try{
 if(e.id==='aacs-editor-font'){changeEditorFont(e.value);return;}
 if(e.id==='aacs-editor-size'){changeEditorFontSize(e.value);return;}
 if(e.dataset.coverUpload){await uploadCover(e.dataset.coverUpload,e.files&&e.files[0]);return;}
 if(e.id==='aacs-project-select'){if(e.value){await openProject(parseInt(e.value,10));}else{s.project=null;s.doc=null;s.docs=[];render();}}
 if(e.id==='aacs-format'){const ed=getEditor();if(ed){ed.focus();document.execCommand('formatBlock',false,e.value);s.doc.content=ed.innerHTML;dirty();}}
 if(e.id==='aacs-scheme'){s.rhymeScheme=e.value;render();}
 }catch(err){note(err.message,true);}});
window.addEventListener('beforeunload',ev=>{if(s.docDirty && s.prefs.saveReminder!=='0'){ev.preventDefault();ev.returnValue='';}});
root.innerHTML='<div class="aacs-loading">✧ Opening your Creative Studio…</div>';init();
})();
